// The tables of one truncation level; a table with no modes for an untabulated level.
inline c_EccentricitySeriesTable c_eccentricity_series_l4(int truncation) noexcept {
    switch (truncation) {
        case 2: return c_EccentricitySeriesTable{4, 2, c_eccentricity_modes_l4_e2, c_eccentricity_coeffs_l4_e2};
        case 4: return c_EccentricitySeriesTable{4, 4, c_eccentricity_modes_l4_e4, c_eccentricity_coeffs_l4_e4};
        case 6: return c_EccentricitySeriesTable{4, 6, c_eccentricity_modes_l4_e6, c_eccentricity_coeffs_l4_e6};
        case 8: return c_EccentricitySeriesTable{4, 8, c_eccentricity_modes_l4_e8, c_eccentricity_coeffs_l4_e8};
        case 10: return c_EccentricitySeriesTable{4, 10, c_eccentricity_modes_l4_e10, c_eccentricity_coeffs_l4_e10};
        case 20: return c_EccentricitySeriesTable{4, 20, c_eccentricity_modes_l4_e20, c_eccentricity_coeffs_l4_e20};
        case 50: return c_EccentricitySeriesTable{4, 50, c_eccentricity_modes_l4_e50, c_eccentricity_coeffs_l4_e50};
        default: return c_EccentricitySeriesTable{};
    }
}
